export const metaText=(item,key,lang='en')=>item[key]?.[lang]||item[key]?.en||'';
export const character=id=>CHARACTERS.find(c=>c.id===id);
export const freshChallenge=()=>({characterWins:[],mapWins:{},bestKills:0,bestRituals:0,noHitBosses:0,fastBosses:0,ritualKills:0,chests:0,limitedWins:0,artifactlessWins:0,flawlessWins:0});
export const freshMeta=()=>({characters:['rasa'],selectedCharacter:'rasa',achievementClaims:[],challenge:freshChallenge(),stats:{kills:0,guardians:0,rituals:0}});
export function validateMeta(s){
 for(const [key,ids] of [['characters',CHARACTERS],['achievementClaims',ACHIEVEMENTS]])if(!Array.isArray(s[key])||new Set(s[key]).size!==s[key].length||s[key].some(id=>!ids.some(x=>x.id===id)))throw Error('Invalid character or achievement history');
 if(s.achievementExtras!==undefined&&(!Array.isArray(s.achievementExtras)||new Set(s.achievementExtras).size!==s.achievementExtras.length||s.achievementExtras.some(id=>!s.achievementClaims.includes(id))))throw Error('Invalid achievement rewards');
 if(!s.characters.includes('rasa')||!s.characters.includes(s.selectedCharacter))throw Error('Invalid selected character');
 if(s.schema>=6){const c=s.challenge;if(!c||!Array.isArray(c.characterWins)||new Set(c.characterWins).size!==c.characterWins.length||c.characterWins.some(id=>!CHARACTERS.some(x=>x.id===id))||!c.mapWins||Object.entries(c.mapWins).some(([id,n])=>!['village','quarry','mill','marsh','bellwood'].includes(id)||!Number.isSafeInteger(n)||n<0)||Object.keys(freshChallenge()).filter(k=>!['characterWins','mapWins'].includes(k)).some(k=>!Number.isSafeInteger(c[k])||c[k]<0))throw Error('Invalid challenge history');}
 if(!s.stats||['kills','guardians','rituals'].some(k=>!Number.isSafeInteger(s.stats[k])||s.stats[k]<0))throw Error('Invalid lifetime statistics');
}
export function buyCharacter(s,id){const c=character(id);if(!c||s.characters.includes(id)||s.gold<c.price)return false;s.gold-=c.price;s.characters.push(id);if(!s.collectedWeapons.includes(c.weapon))s.collectedWeapons.push(c.weapon);return true;}
export function selectCharacter(s,id){if(!s.characters.includes(id))return false;s.selectedCharacter=id;return true;}
export function achievementProgress(s,a){let n=0;switch(a.metric){
 case 'kills':case 'guardians':case 'rituals':n=s.stats?.[a.metric]||0;break;
 case 'runs':case 'bosses':n=s[a.metric];break;case 'survival':n=s.best;break;
 case 'map':n=s.clearedMaps.includes(a.mapId)?1:0;break;
 case 'weapons':n=s.collectedWeapons.length;break;case 'characters':n=s.characters.length;break;
 case 'evolutions':n=s.discovered.filter(id=>RECIPES.some(r=>r.id===id)).length;break;
 case 'ultimates':n=s.discovered.filter(id=>ULTIMATES.some(r=>r.id===id)).length;break;
 case 'character_win':n=s.challenge?.characterWins?.includes(a.characterId)?1:0;break;
 case 'map_wins':n=s.challenge?.mapWins?.[a.mapId]||0;break;
 case 'capstone':n=s.skills.includes(a.skillId)?1:0;break;
 case 'bestKills':case 'bestRituals':case 'noHitBosses':case 'fastBosses':case 'ritualKills':case 'chests':case 'limitedWins':case 'artifactlessWins':case 'flawlessWins':n=s.challenge?.[a.metric]||0;break;
 case 'rank':n=Math.max(0,...Object.values(s.ranks));break;
 }return Math.min(a.target,Math.max(0,Math.floor(n)));}
const CHARACTER_REWARDS={kills_2:'mira',bosses_2:'kael',map_quarry:'neris',evolutions_1:'vesper',map_mill:'elin',no_hit_5:'morwen',map_marsh:'astra',chests_100:'selene',map_bellwood:'brann',limited_win:'corvin',flawless_win:'talis'};
export const achievementReward=a=>({gold:a.reward,shards:Math.max(1,Math.ceil(a.reward/125)),character:CHARACTER_REWARDS[a.id]||null});
export const achievementClaimed=(s,id)=>s.achievementClaims.includes(id)&&(s.achievementExtras||[]).includes(id);
export const readyAchievements=s=>ACHIEVEMENTS.filter(a=>!achievementClaimed(s,a.id)&&(s.achievementClaims.includes(a.id)||achievementProgress(s,a)>=a.target));
export function claimAchievement(s,id){const a=ACHIEVEMENTS.find(a=>a.id===id);if(!a||achievementClaimed(s,id)||!s.achievementClaims.includes(id)&&achievementProgress(s,a)<a.target)return false;
 const reward=achievementReward(a);if(!s.achievementClaims.includes(id)){s.achievementClaims.push(id);s.gold+=reward.gold;}
 s.achievementExtras||=[];if(!s.achievementExtras.includes(id)){s.achievementExtras.push(id);s.shards+=reward.shards;if(reward.character){const c=character(reward.character);if(!s.characters.includes(c.id))s.characters.push(c.id);if(!s.collectedWeapons.includes(c.weapon))s.collectedWeapons.push(c.weapon);}}
 return true;}

